package com.example.starter.spectrum;

/**
 * 租约占用模式。
 */
public enum LeaseMode {

    /** 独占：与任意相遇租约冲突。 */
    EXCLUSIVE,

    /** 共享：可与其他共享租约相遇，但片段内生效 EIRP 总和受上限约束。 */
    SHARED
}

package com.example.starter.spectrum.config;

import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * 频谱租约协调配置。
 *
 * @param sharedEirpLimitMw 全共享场景下，任意实际重叠的时间×频率×区域片段内
 *                          生效租约 EIRP 总和上限，单位 mW
 */
@ConfigurationProperties(prefix = "spectrum.lease")
public record SpectrumProperties(java.math.BigDecimal sharedEirpLimitMw) {
}

package com.example.starter.spectrum;

import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Configuration;

/**
 * 频谱租约协调模块的 Spring 配置入口。
 */
@Configuration
@EnableConfigurationProperties(SpectrumProperties.class)
public class SpectrumConfig {
}

