     * @param httpStatus HTTP 状态码
     * @param body       响应体
     * @param leaseId    关联租约标识（可能为空）
     */
    record ServiceResult(int httpStatus, Object body, String leaseId) {
    }

    /** 创建（含请求指纹幂等）。 */
