    /** 修改（追加版本，含 expectedVersion 乐观校验与请求指纹幂等）。 */
    ServiceResult modify(ModifyLeaseRequest request);

    /** 取消（只改变未来有效性；终态同参重复取消无副作用成功）。 */
    ServiceResult cancel(CancelLeaseRequest request);

    /** 指定 UTC 时刻的活动租约快照。 */
